public void start(UPoint hanBase, Unit controlled) {
    this.mPivotDistance = MathUtils.getLength(controlled.getBasePoint().x, controlled.getBasePoint().y, hanBase.x, hanBase.y);
    this.mStructuresList.clear();
    Scene scene = controlled.getScene();
    String name = controlled.getName();
    for (Frame frame : scene.selectedRange().frames()) {
        int indexOf = scene.getIndexOf(frame);
        if (scene.tweens().isAutoTweenLocked(name, indexOf)) {
            throw new IllegalStateException(scene.tweens().autoTweenLockMessage(name, indexOf));
        }
        Unit unitOrNull = frame.findUnitByExactName(controlled.getName()).orNull();
        if (unitOrNull != null) {
            this.mStructuresList.put(Integer.valueOf(indexOf), new Structure(unitOrNull));
        }
    }
}
